import{_ as s,C as d,o as t,c as n,a2 as a,b as l,w as i,a as r,E as c,a3 as p}from"./chunks/framework.CZqXuAiL.js";const v=JSON.parse('{"title":"Configuration Validation & Runtime Updates","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/configuration/validation.md","filePath":"openshield-xdp/configuration/validation.md","lastUpdated":null}'),h={name:"openshield-xdp/configuration/validation.md"};function u(g,e,m,f,b,k){const o=d("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a(`<h1 id="configuration-validation-runtime-updates" tabindex="-1">Configuration Validation &amp; Runtime Updates <a class="header-anchor" href="#configuration-validation-runtime-updates" aria-label="Permalink to &quot;Configuration Validation &amp; Runtime Updates&quot;">​</a></h1><h2 id="config-file-location" tabindex="-1">Config File Location <a class="header-anchor" href="#config-file-location" aria-label="Permalink to &quot;Config File Location&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/etc/openshield/openshield.yaml</span></span></code></pre></div><p>OpenShield-XDP reads its YAML configuration from this path on startup. An annotated example ships with the package:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/opt/openshield/share/openshield.example.yaml</span></span></code></pre></div><p>Generate a fresh copy of the defaults:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Writes /etc/openshield/openshield.yaml with all default values</span></span></code></pre></div><h2 id="yaml-validation-rules" tabindex="-1">YAML Validation Rules <a class="header-anchor" href="#yaml-validation-rules" aria-label="Permalink to &quot;YAML Validation Rules&quot;">​</a></h2><p>The config file is validated using JSON-schema-like rules implemented in Go (<code>userspace/internal/config/metadata.go</code>). Each field has:</p><table tabindex="0"><thead><tr><th>Constraint</th><th>Description</th></tr></thead><tbody><tr><td><strong>Type check</strong></td><td><code>int</code>, <code>float64</code>, <code>bool</code>, or <code>string</code> — strictly enforced</td></tr><tr><td><strong>Range / enum</strong></td><td>Most fields have min/max bounds (e.g., <code>pps_threshold</code> must be <code>1 – 10,000,000</code>)</td></tr><tr><td><strong>String enum</strong></td><td><code>rate_limit_mode</code> must be <code>&quot;threshold&quot;</code> or <code>&quot;token_bucket&quot;</code>; <code>xdp_mode</code> must be <code>&quot;auto&quot;</code>, <code>&quot;native&quot;</code>, <code>&quot;generic&quot;</code>, or <code>&quot;offload&quot;</code></td></tr><tr><td><strong>Array length</strong></td><td><code>udp_amp_ports</code> and <code>udp_amp_payload_min</code> are capped at 8 entries; <code>mac_filter_entries</code> at 8</td></tr></tbody></table><p>If validation fails, the loader exits with a descriptive error:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>invalid config: static.pps_threshold must be 1-10000000 (got 0)</span></span></code></pre></div><h2 id="runtime-configuration-updates" tabindex="-1">Runtime Configuration Updates <a class="header-anchor" href="#runtime-configuration-updates" aria-label="Permalink to &quot;Runtime Configuration Updates&quot;">​</a></h2><p>OpenShield supports <strong>live config changes</strong> without restarting the XDP program via a Unix domain socket:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/var/run/openshield/config.sock</span></span></code></pre></div><h3 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Root-Only Access</p><p>The Unix socket is protected by <code>SO_PEERCRED</code> — only the root user can connect. This is not a general-purpose API; it&#39;s the internal communication channel between <code>openshield</code> CLI commands and the running loader daemon.</p></div>`,17)),(t(),l(p,null,{default:i(()=>[c(o,{id:"mermaid-86",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20CLI%20as%20openshield%20CLI%20(root)%0A%20%20%20%20participant%20Sock%20as%20%2Fvar%2Frun%2Fopenshield%2Fconfig.sock%0A%20%20%20%20participant%20LDR%20as%20Loader%20Daemon%20(root)%0A%20%20%20%20participant%20XDP%20as%20XDP%20Program%20(kernel)%0A%0A%20%20%20%20CLI-%3E%3ESock%3A%20connect()%20%2B%20SO_PEERCRED%20check%0A%20%20%20%20Sock--%3E%3ECLI%3A%20authenticated%0A%20%20%20%20CLI-%3E%3ELDR%3A%20JSON%20write%3A%20%7B%22field%22%3A%22static.pps_threshold%22%2C%22value%22%3A500%7D%0A%20%20%20%20LDR-%3E%3ELDR%3A%20validate%20field%20(type%2C%20range)%0A%20%20%20%20LDR-%3E%3EXDP%3A%20bpf_map_update_elem(config_map)%0A%20%20%20%20XDP--%3E%3ELDR%3A%20OK%0A%20%20%20%20LDR--%3E%3ECLI%3A%20%7B%22status%22%3A%22ok%22%7D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<h3 id="which-fields-require-a-restart" tabindex="-1">Which Fields Require a Restart? <a class="header-anchor" href="#which-fields-require-a-restart" aria-label="Permalink to &quot;Which Fields Require a Restart?&quot;">​</a></h3><p>The config metadata system marks each field as <strong>RuntimeSafe</strong> or not.</p><p><strong>🔄 Runtime-safe fields</strong> (updated instantly via socket):</p><ul><li>All <code>static.*</code> thresholds, scores, decays</li><li>All <code>validation.*</code> booleans</li><li>All <code>dynamic.*</code> detection toggles and thresholds</li><li><code>whitelist.enabled</code></li><li><code>telemetry.event_rate_limit</code>, <code>top_offenders_count</code>, <code>log_level</code>, <code>snapshot_interval</code></li><li><code>maps.bloom_filter_enabled</code>, <code>maps.bloom_filter_size</code></li><li><code>alerter.*</code></li></ul><p><strong>🔒 Fields requiring <code>openshield fix &amp;&amp; openshield load</code>:</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Reason</th></tr></thead><tbody><tr><td><code>interface</code></td><td>Requires XDP reattach to new netdev</td></tr><tr><td><code>xdp_mode</code></td><td>Requires XDP reattach in new mode</td></tr><tr><td><code>maps.ip_stats_max</code></td><td>Requires map recreation (resize)</td></tr><tr><td><code>maps.ban_max</code></td><td>Requires map recreation</td></tr><tr><td><code>maps.whitelist_max</code></td><td>Requires map recreation</td></tr><tr><td><code>maps.event_buffer_size</code></td><td>Requires ring buffer recreation</td></tr><tr><td><code>dynamic.baseline_window</code></td><td>Affects baseline learner goroutine timing</td></tr><tr><td><code>dynamic.baseline_update_interval</code></td><td>Affects baseline learner goroutine timing</td></tr><tr><td><code>dynamic.baseline_alpha</code></td><td>Affects baseline learner calculation</td></tr><tr><td><code>telemetry.poll_interval</code></td><td>Affects collector goroutine timing</td></tr></tbody></table><h2 id="config-generator" tabindex="-1">Config Generator <a class="header-anchor" href="#config-generator" aria-label="Permalink to &quot;Config Generator&quot;">​</a></h2><p>The <code>openshield config</code> command programmatically generates a config file with all defaults:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate defaults (overwrites existing file)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate to a specific path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/my-config.yaml</span></span></code></pre></div><p>It reads the <code>Defaults()</code> function from <code>userspace/internal/config/defaults.go</code> and serializes all fields with descriptive comments, ensuring the output always matches the latest config schema.</p><h2 id="per-ip-whitelist-flags" tabindex="-1">Per-IP Whitelist Flags <a class="header-anchor" href="#per-ip-whitelist-flags" aria-label="Permalink to &quot;Per-IP Whitelist Flags&quot;">​</a></h2><p>When whitelisting an IP, the userspace loader stores a <strong>flags byte</strong> in the whitelist map controlling what checks are bypassed:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td>Full bypass</td><td><code>0x00</code></td><td>Skip <strong>all</strong> checks (packet passes immediately)</td></tr><tr><td>Skip ban</td><td><code>0x01</code></td><td>Skip ban and subnet ban lookups</td></tr><tr><td>Skip rate</td><td><code>0x02</code></td><td>Skip rate threshold and scoring</td></tr><tr><td>Skip validation</td><td><code>0x04</code></td><td>Skip private/bogon/bogus TCP checks</td></tr></tbody></table><p>Flags are bitwise-OR&#39;d. For example, <code>0x03</code> skips both ban and rate checks.</p><h2 id="empty-map-fast-paths" tabindex="-1">Empty-Map Fast Paths <a class="header-anchor" href="#empty-map-fast-paths" aria-label="Permalink to &quot;Empty-Map Fast Paths&quot;">​</a></h2><p>To save lookup overhead when maps contain zero entries:</p><ul><li><strong><code>whitelist_empty</code> flag</strong>: Set to <code>1</code> in <code>config_map</code> when the whitelist map has 0 entries. The XDP program skips all whitelist lookups.</li><li><strong><code>bans_empty</code> flag</strong>: Set to <code>1</code> when both <code>ban_map</code> and <code>subnet_ban_map</code> are empty.</li></ul><p>Both flags are updated by the userspace loader after every config change (including runtime socket updates). This eliminates ~200-400ns of map lookup latency when these maps are unused.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./reference">Configuration Reference</a> — Complete field reference with defaults</li><li><a href="./alerter">Alerter</a> — Webhook alert configuration</li><li><a href="/pingless-studios-docs/openshield-xdp/developer-guide/overview">Developer Guide</a> — Adding new config fields</li></ul>`,20))])}const y=s(h,[["render",u]]);export{v as __pageData,y as default};
